namespace ntt {

inline constexpr std::uint32_t kModulus = kernels::kP;
inline constexpr int kMaxLog = 25;  // products of up to 2^25 coefficients

namespace detail {

using kernels::Vec;
using kernels::kP;

constexpr std::uint32_t multiply_mod(std::uint32_t x, std::uint32_t y) {
    return std::uint32_t(std::uint64_t(x) * y % kP);
}

constexpr std::uint32_t power(std::uint32_t x, std::uint32_t e) {
    std::uint32_t r = 1;
    for (; e; e >>= 1, x = multiply_mod(x, x))
        if (e & 1) r = multiply_mod(r, x);
    return r;
}

// Shoup quotient floor(w 2^32 / P) of a constant w < P.
constexpr std::uint32_t quotient(std::uint32_t w) { return std::uint32_t((std::uint64_t(w) << 32) / kP); }

inline constexpr std::uint32_t kR = std::uint32_t((std::uint64_t(1) << 32) % kP);  // 2^32 mod P

// kRoots[j] has order 2^(j + 2); 3 generates the multiplicative group.
inline constexpr int kRootCount = kMaxLog - 4;
inline constexpr auto kRoots = [] {
    std::array<std::array<std::uint32_t, kRootCount>, 2> t{};  // forward, inverse
    for (int j = 0; j < kRootCount; ++j) {
        t[0][j] = power(3, (kP - 1) >> (j + 2));
        t[1][j] = power(t[0][j], kP - 2);
    }
    return t;
}();

inline Vec broadcast(std::uint32_t x) { return _mm256_set1_epi32(int(x)); }
inline Vec add(Vec x, Vec y) { return _mm256_add_epi32(x, y); }
inline Vec diff(Vec x, Vec y) { return _mm256_sub_epi32(_mm256_add_epi32(x, broadcast(2 * kP)), y); }  // x - y + 2P

// x < 2 bound -> x mod bound.
inline Vec reduce(Vec x, std::uint32_t bound) { return _mm256_min_epu32(x, _mm256_sub_epi32(x, broadcast(bound))); }

// A constant factor w < P and its Shoup quotient.
struct Factor {
    Vec w, q;
    explicit Factor(std::uint32_t value) : w(broadcast(value)), q(broadcast(quotient(value))) {}
    Factor(std::uint32_t value, std::uint32_t value_quotient) : w(broadcast(value)), q(broadcast(value_quotient)) {}
};

// x w mod P in [0, 2P), for any x < 2^32.
inline Vec multiply(Vec x, const Factor& f) {
    const Vec even = _mm256_srli_epi64(_mm256_mul_epu32(x, f.q), 32);
    const Vec odd = _mm256_mul_epu32(_mm256_srli_epi64(x, 32), f.q);
    const Vec q = _mm256_blend_epi32(even, odd, 0xAA);
    return _mm256_sub_epi32(_mm256_mullo_epi32(x, f.w), _mm256_mullo_epi32(q, broadcast(kP)));
}

// Twiddle tables: entry k is the product of roots[j] over the set bits j of k, so entry 1 is
// sqrt(-1) and entry 2k is a square root of entry k. Blocks of 8 values, then their 8 quotients.
inline std::size_t slot(std::size_t k) { return (k >> 3 << 4) | (k & 7); }

inline std::size_t table_words(int lg) { return (std::size_t(1) << lg) / 8 + 16; }

// Entries [0, count) of the table for roots.
inline void build_table(std::uint32_t* t, std::size_t count, const std::array<std::uint32_t, kRootCount>& roots) {
    t[slot(0)] = 1;
    t[slot(0) + 8] = quotient(1);
    for (std::size_t h = 1; h < count; h *= 2) {
        const std::uint32_t root = roots[std::countr_zero(h)];
        if (h < 8) {
            for (std::size_t j = 0; j < h; ++j) {
                const std::uint32_t v = multiply_mod(t[slot(j)], root);
                t[slot(h + j)] = v;
                t[slot(h + j) + 8] = quotient(v);
            }
            continue;
        }
        // Quotient of v: (v 2^32 mod P) / -P mod 2^32.
        const Factor by(root), to_r(kR);
        for (std::size_t j = 0; j < h; j += 8) {
            const Vec v = reduce(multiply(_mm256_load_si256(reinterpret_cast<const Vec*>(t + slot(j))), by), kP);
            const Vec vr = reduce(multiply(v, to_r), kP);
            _mm256_store_si256(reinterpret_cast<Vec*>(t + slot(h + j)), v);
            _mm256_store_si256(reinterpret_cast<Vec*>(t + slot(h + j) + 8), _mm256_mullo_epi32(vr, broadcast(kernels::kNI)));
        }
    }
}

// Depth-first recursion over radix-4 groups. Group k at stride h holds 4h vectors, a polynomial
// mod X^4 - r[k]^2 with X = x^(8h); its outputs are the children 4k + t. A vector is a leaf: a
// polynomial mod x^8 - w, multiplied directly.
class Recursion {
public:
    Recursion(const std::uint32_t* roots, const std::uint32_t* inverse_roots) : r_(roots), ir_(inverse_roots) {}

    // Forward transforms of a and b, leaf products into a, inverse transform; nv a power of 4.
    void visit(Vec* a, Vec* b, std::size_t nv, std::size_t k) const {
        switch (nv) {
        case 4: return tile<4>(a, b, k);
        case 16: return tile<16>(a, b, k);
        case 64: return tile<64>(a, b, k);
        case 256: return tile<256>(a, b, k);
        }
        const std::size_t h = nv / 4;
        forward(a, b, h, k);
        for (std::size_t t = 0; t < 4; ++t) visit(a + t * h, b + t * h, h, 4 * k + t);
        inverse(a, h, k);
    }

private:
    // A subtree small enough for L2, level by level.
    template <std::size_t NV>
    [[gnu::noinline]] void tile(Vec* a, Vec* b, std::size_t k) const {
        for (std::size_t h = NV / 4; h >= 4; h /= 4)
            for (std::size_t j = 0, g = k * (NV / (4 * h)); j < NV; j += 4 * h, ++g) forward(a + j, b + j, h, g);
        bottom(a, b, NV, k * (NV / 4));
        for (std::size_t h = 4; h < NV; h *= 4)
            for (std::size_t j = 0, g = k * (NV / (4 * h)); j < NV; j += 4 * h, ++g) inverse(a + j, h, g);
    }

    void forward(Vec* a, Vec* b, std::size_t h, std::size_t k) const {
        if (k == 0) {
            kernels::forward_identity(a, h, r_);
            kernels::forward_identity(b, h, r_);
            return;
        }
        const std::uint32_t *x = r_ + slot(k), *y = r_ + slot(2 * k);
        if (h == 4) return kernels::forward_pair(a, b, h, x, y);
        kernels::forward(a, h, x, y);
        kernels::forward(b, h, x, y);
    }

    void inverse(Vec* a, std::size_t h, std::size_t k) const {
        if (k == 0) return kernels::inverse_identity(a, h, ir_);
        kernels::inverse(a, h, ir_ + slot(k), ir_ + slot(2 * k));
    }

    struct alignas(64) Leaves {
        std::uint32_t window[4][16];  // [w A_t, A_t]: x^i A_t mod x^8 - w is a sliding window
        std::uint32_t coefficients[4][8];
    };

    // Moduli x^8 - w of the four leaves under group k: w = y, -y, z, -z, then their quotients.
    void leaf_weights(std::size_t k, std::uint32_t* w) const {
        const std::uint32_t* y = r_ + slot(2 * k);
        w[0] = y[0], w[1] = kP - y[0], w[2] = y[1], w[3] = kP - y[1];
        w[4] = y[8], w[5] = ~y[8], w[6] = y[9], w[7] = ~y[9];  // quotient(P - w) = ~quotient(w)
    }

    // Groups [first, first + nv / 4) with h = 1 and their leaves; batch j + 1's forward half
    // overlaps batch j's products and inverse.
    void bottom(Vec* a, Vec* b, std::size_t nv, std::size_t first) const {
        Leaves leaves[2];
        alignas(32) std::uint32_t w[2][8];
        leaf_weights(first, w[0]);
        kernels::bottom_first(a, b, &leaves[0], r_ + slot(first), r_ + slot(2 * first), w[0]);
        for (std::size_t j = 0, k = first; j < nv; j += 4, ++k) {
            const std::size_t cur = j / 4 % 2, next = cur ^ 1;
            const std::uint32_t *ix = ir_ + slot(k), *iy = ir_ + slot(2 * k);
            if (j + 4 == nv) {
                kernels::bottom_last(a + j, &leaves[cur], ix, iy);
                break;
            }
            leaf_weights(k + 1, w[next]);
            kernels::bottom_both(a + j + 4, b + j + 4, &leaves[next], r_ + slot(k + 1), r_ + slot(2 * k + 2), w[next],
                                 a + j, &leaves[cur], ix, iy);
        }
    }

    const std::uint32_t *r_, *ir_;
};

// Inputs of the first level are canonical. If an input's upper half is zero ("sparse"), the
// first radix-2 level is a copy and the first radix-4 level reads only the lower half.

// f[i] and f[i + h] for i < h -> their sum and difference, < 2P.
inline void forward_radix2(Vec* f, std::size_t h, bool sparse) {
    if (sparse) {
        std::memcpy(f + h, f, h * sizeof(Vec));
        return;
    }
    for (std::size_t i = 0; i < h; ++i) {
        const Vec x = f[i], y = f[i + h];
        f[i] = reduce(add(x, y), 2 * kP);
        f[i + h] = reduce(diff(x, y), 2 * kP);
    }
}

// forward_identity() on canonical input; z = r[1].
inline void forward_radix4(Vec* f, std::size_t h, bool sparse, const std::uint32_t* roots) {
    if (!sparse) return kernels::forward_identity(f, h, roots);
    const Factor z(roots[1], roots[9]);
    for (std::size_t j = 0; j < h; ++j) {
        const Vec a = f[j], b = f[j + h], zb = multiply(b, z);  // < 4P
        f[j] = add(a, b), f[j + h] = diff(a, b), f[j + 2 * h] = add(a, zb), f[j + 3 * h] = diff(a, zb);
    }
}

// inverse_identity() and the scale s: canonical output; z = r^-1[1].
inline void inverse_radix4(Vec* f, std::size_t h, const std::uint32_t* inverse_roots, const Factor& s) {
    const Factor z(inverse_roots[1], inverse_roots[9]);
    const auto scale = [&s](Vec x) { return reduce(multiply(x, s), kP); };
    for (std::size_t j = 0; j < h; ++j) {
        const Vec p0 = f[j], p1 = f[j + h], p2 = f[j + 2 * h], p3 = f[j + 3 * h];  // < 2P
        const Vec ab = reduce(add(p0, p1), 2 * kP), cd = reduce(add(p2, p3), 2 * kP);
        const Vec amb = reduce(diff(p0, p1), 2 * kP), cmd = multiply(diff(p2, p3), z);
        f[j] = scale(add(ab, cd)), f[j + h] = scale(add(amb, cmd));
        f[j + 2 * h] = scale(diff(ab, cd)), f[j + 3 * h] = scale(diff(amb, cmd));
    }
}

}  // namespace detail

// a * b for a of n and b of m coefficients, n, m >= 1, n + m - 1 <= 2^kMaxLog. Single use.
class Convolution {
public:
    Convolution(std::size_t n, std::size_t m)
        : n_(n), m_(m), lg_(std::max(6, int(std::bit_width(n + m - 2)))) {
        if (n == 0 || m == 0 || lg_ > kMaxLog) std::abort();
        const std::size_t len = length(), words = 2 * (len + kPadding) + 2 * detail::table_words(lg_);
        constexpr std::size_t kHuge = std::size_t(1) << 21;
        bytes_ = (words * sizeof(std::uint32_t) + kHuge - 1) / kHuge * kHuge + kHuge;
        region_ = ::mmap(nullptr, bytes_, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (region_ == MAP_FAILED) std::abort();
        const std::uintptr_t aligned = (reinterpret_cast<std::uintptr_t>(region_) + kHuge - 1) & ~(kHuge - 1);
        auto* start = reinterpret_cast<std::uint32_t*>(aligned);
#ifdef MADV_HUGEPAGE
        ::madvise(start, bytes_ - kHuge, MADV_HUGEPAGE);
#endif
        a_ = start;
        b_ = a_ + len + kPadding;
        roots_ = b_ + len + kPadding;
        inverse_roots_ = roots_ + detail::table_words(lg_);
    }

    ~Convolution() { ::munmap(region_, bytes_); }

    Convolution(const Convolution&) = delete;
    Convolution& operator=(const Convolution&) = delete;

    // The factors, zero-filled: n and m coefficients < kModulus.
    std::uint32_t* a() { return a_; }
    std::uint32_t* b() { return b_; }

    // The n + m - 1 coefficients of a * b, canonical, in a(); b() is destroyed.
    const std::uint32_t* multiply() {
        using namespace detail;
        const std::size_t len = length(), nv = len / 8;
        build_table(roots_, len / 16, kRoots[0]);
        build_table(inverse_roots_, len / 16, kRoots[1]);
        const Recursion recursion(roots_, inverse_roots_);
        const std::uint32_t scale = multiply_mod(power(std::uint32_t(nv), kP - 2), kR);  // undoes nv / 2^32
        auto* a = reinterpret_cast<Vec*>(a_);
        auto* b = reinterpret_cast<Vec*>(b_);
        const bool sparse_a = n_ <= len / 2, sparse_b = m_ <= len / 2;
        if (std::countr_zero(nv) % 2) {  // nv = 2 * 4^j
            const std::size_t h = nv / 2;
            forward_radix2(a, h, sparse_a);
            forward_radix2(b, h, sparse_b);
            recursion.visit(a, b, h, 0);
            recursion.visit(a + h, b + h, h, 1);
            alignas(32) std::uint32_t s[16] = {};  // table layout: s at entry 1
            s[1] = scale;
            s[9] = quotient(scale);
            kernels::scale_radix2(a, h, s);
        } else {  // nv = 4^j
            const std::size_t h = nv / 4;
            forward_radix4(a, h, sparse_a, roots_);
            forward_radix4(b, h, sparse_b, roots_);
            for (std::size_t t = 0; t < 4; ++t) recursion.visit(a + t * h, b + t * h, h, t);
            inverse_radix4(a, h, inverse_roots_, Factor(scale));
        }
        return a_;
    }

private:
    static constexpr std::size_t kPadding = 16;  // words after each factor: the kernels read 4 bytes past

    std::size_t length() const { return std::size_t(1) << lg_; }

    std::size_t n_, m_;
    int lg_;
    void* region_;
    std::size_t bytes_;
    std::uint32_t *a_, *b_, *roots_, *inverse_roots_;
};

}  // namespace ntt
// problems/convolution/convolution_mod/fields.hpp
// Fixed-width output of residues < 10^9, byte for byte as ../fixed_width.hpp: each value
// right-aligned in 9 characters, then a space; the last separator is a newline. Judge-specific:
// the checker compares tokens, so the padding is accepted.
//
// 16 values per step, written as ten 16-byte chunks. The divisions of the next step are issued
// before the digits of this one, so the two dependency chains overlap.


namespace fields {

namespace detail {

struct alignas(32) Lanes {
    std::uint32_t lane[8];
};

constexpr Lanes all(std::uint32_t x) { return {{x, x, x, x, x, x, x, x}}; }
constexpr Lanes all16(std::uint32_t x) { return all(x * 0x10001); }

constexpr int Z = 0x80;  // shuffle control: zero byte

// The same 16-byte shuffle control in both lanes.
constexpr Lanes shuffle(const int (&b)[16]) {
    Lanes t{};
    for (int i = 0; i < 32; ++i) t.lane[i / 4] |= std::uint32_t(b[i % 16] & 0xFF) << 8 * (i % 4);
    return t;
}

struct Constants {
    Lanes div10 = all(429496730);     // ceil(2^32 / 10): v / 10 = v * div10 >> 32 for v < 2^30
    Lanes div10e5 = all(1407374884);  // ceil(2^47 / 10^5): v / 10^5 = v * div10e5 >> 47
    Lanes pack = all(1 - 10000 * 65536u);  // [h, w - 10^4 h] in 16-bit halves = 2^16 w + h pack
    Lanes ten = all(10);
    Lanes tail = all(' ' << 8 | '0');
    Lanes by100 = all16(5243), hundred = all16(100);  // x / 100 = (x * 5243 >> 16) >> 3 for x < 10^4
    Lanes by10 = all16(6554);  // z / 10 = z * 6554 >> 16 for z < 100
    Lanes tens_out = all16(2559);  // bytes [z / 10, z % 10] = 256 z - 2559 (z / 10)
    Lanes ones = all(~0u), zero = all(0x30303030), space = all(0x20202020);
    // Chunk c of a step: text bytes [16c, 16c + 16) of values 0-7 in the low lane, of values 8-15
    // in the high lane. Sources, each lane: digits of two values (8 bytes each), or four tails
    // (2 bytes in each dword). Comments: field bytes of the low lane.
    Lanes chunk0[2] = {shuffle({0, 1, 2, 3, 4, 5, 6, 7, Z, Z, 8, 9, 10, 11, 12, 13}),  // D0 D1
                       shuffle({Z, Z, Z, Z, Z, Z, Z, Z, 0, 1, Z, Z, Z, Z, Z, Z})};     // T0
    Lanes chunk1[3] = {shuffle({14, 15, Z, Z, Z, Z, Z, Z, Z, Z, Z, Z, Z, Z, Z, Z}),    // D1
                       shuffle({Z, Z, 4, 5, Z, Z, Z, Z, Z, Z, Z, Z, 8, 9, Z, Z}),      // T1 T2
                       shuffle({Z, Z, Z, Z, 0, 1, 2, 3, 4, 5, 6, 7, Z, Z, 8, 9})};     // D2 D3
    Lanes chunk2[3] = {shuffle({10, 11, 12, 13, 14, 15, Z, Z, Z, Z, Z, Z, Z, Z, Z, Z}),  // D3
                       shuffle({Z, Z, Z, Z, Z, Z, 12, 13, Z, Z, Z, Z, Z, Z, Z, Z}),      // T3
                       shuffle({Z, Z, Z, Z, Z, Z, Z, Z, 0, 1, 2, 3, 4, 5, 6, 7})};       // D4
    Lanes chunk3[3] = {shuffle({0, 1, Z, Z, Z, Z, Z, Z, Z, Z, 4, 5, Z, Z, Z, Z}),        // T4 T5
                       shuffle({Z, Z, 8, 9, 10, 11, 12, 13, 14, 15, Z, Z, Z, Z, Z, Z}),  // D5
                       shuffle({Z, Z, Z, Z, Z, Z, Z, Z, Z, Z, Z, Z, 0, 1, 2, 3})};       // D6
    Lanes chunk4[2] = {shuffle({4, 5, 6, 7, Z, Z, 8, 9, 10, 11, 12, 13, 14, 15, Z, Z}),  // D6 D7
                       shuffle({Z, Z, Z, Z, 8, 9, Z, Z, Z, Z, Z, Z, Z, Z, 12, 13})};     // T6 T7
};

inline constexpr Constants kConstants{};

[[gnu::always_inline]] inline __m256i load(const Lanes& l) {
    return _mm256_load_si256(reinterpret_cast<const __m256i*>(&l));
}

[[gnu::always_inline]] inline __m256i shuffle(__m256i x, const Lanes& control) {
    return _mm256_shuffle_epi8(x, load(control));
}

// Eight values v < 10^9 (dwords) after the divisions by 10 and 10^5: halves holds
// [w / 10^4, w % 10^4] in 16-bit halves for w = v / 10; tail holds the units digit and the
// separator as text.
struct Divided {
    __m256i halves, tail;
};

[[gnu::always_inline]] inline Divided divide(__m256i v, __m256i odd, const Constants& k) {
    const __m256i w = _mm256_blend_epi32(_mm256_srli_epi64(_mm256_mul_epu32(v, load(k.div10)), 32),
                                         _mm256_mul_epu32(odd, load(k.div10)), 0xAA);
    const __m256i h = _mm256_blend_epi32(_mm256_srli_epi64(_mm256_mul_epu32(v, load(k.div10e5)), 47),
                                         _mm256_srli_epi64(_mm256_mul_epu32(odd, load(k.div10e5)), 15), 0xAA);
    const __m256i halves = _mm256_add_epi32(_mm256_slli_epi32(w, 16), _mm256_mullo_epi32(h, load(k.pack)));
    const __m256i tail = _mm256_sub_epi32(_mm256_add_epi32(v, load(k.tail)), _mm256_mullo_epi32(w, load(k.ten)));
    return {halves, tail};
}

// 16-bit z < 100 -> bytes [z / 10, z % 10].
[[gnu::always_inline]] inline __m256i two_digits(__m256i z, const Constants& k) {
    const __m256i tens = _mm256_mulhi_epu16(z, load(k.by10));
    return _mm256_sub_epi16(_mm256_slli_epi16(z, 8), _mm256_mullo_epi16(tens, load(k.tens_out)));
}

// Qwords of 8 digits, most significant first -> text; leading zeros become spaces. x ^ (x - 1)
// sets the bits up to the lowest set one: 0xFF in leading zero bytes, < 0x10 in the first
// nonzero digit, 0 above. blendv takes the space where a byte's top bit is set.
[[gnu::always_inline]] inline __m256i text(__m256i digits, const Constants& k) {
    const __m256i upto = _mm256_xor_si256(digits, _mm256_add_epi64(digits, load(k.ones)));
    return _mm256_blendv_epi8(_mm256_or_si256(digits, load(k.zero)), load(k.space), upto);
}

// Text of the 8 digits of w, two values per lane: values [0, 1 | 4, 5] of d in lo, [2, 3 | 6, 7]
// in hi. Per value, 16-bit [w / 10^6, w / 10^4 % 100, w / 100 % 100, w % 100] before two_digits.
[[gnu::always_inline]] inline void digits(const Divided& d, __m256i& lo, __m256i& hi, const Constants& k) {
    const __m256i hundreds = _mm256_srli_epi16(_mm256_mulhi_epu16(d.halves, load(k.by100)), 3);
    const __m256i rest = _mm256_sub_epi16(d.halves, _mm256_mullo_epi16(hundreds, load(k.hundred)));
    lo = text(two_digits(_mm256_unpacklo_epi16(hundreds, rest), k), k);
    hi = text(two_digits(_mm256_unpackhi_epi16(hundreds, rest), k), k);
}

// 160 bytes at p (16-byte aligned) for values x0..x15, divided as lo = [x0..x3 | x8..x11] and
// hi = [x4..x7 | x12..x15].
[[gnu::always_inline]] inline void store(char* p, const Divided& lo, const Divided& hi, const Constants& k) {
    __m256i d01, d23, d45, d67;  // values x0 x1 | x8 x9, x2 x3 | x10 x11, and so on
    const auto either = [](__m256i a, __m256i b) { return _mm256_or_si256(a, b); };
    digits(lo, d01, d23, k);
    digits(hi, d45, d67, k);
    const __m256i c0 = either(shuffle(d01, k.chunk0[0]), shuffle(lo.tail, k.chunk0[1]));
    const __m256i c1 = either(either(shuffle(d01, k.chunk1[0]), shuffle(lo.tail, k.chunk1[1])), shuffle(d23, k.chunk1[2]));
    const __m256i c2 = either(either(shuffle(d23, k.chunk2[0]), shuffle(lo.tail, k.chunk2[1])), shuffle(d45, k.chunk2[2]));
    const __m256i c3 = either(either(shuffle(hi.tail, k.chunk3[0]), shuffle(d45, k.chunk3[1])), shuffle(d67, k.chunk3[2]));
    const __m256i c4 = either(shuffle(d67, k.chunk4[0]), shuffle(hi.tail, k.chunk4[1]));
    // Chunk c whole at p + 64 + 16c: its high lane lands in place, its low lane on the slot of the
    // previous chunk's high lane (or of chunk 4's low lane), which a later store fixes.
    const auto whole = [p](int c, __m256i chunk) { _mm256_storeu_si256(reinterpret_cast<__m256i*>(p + 64 + 16 * c), chunk); };
    const auto low = [p](int c, __m256i chunk) { _mm_store_si128(reinterpret_cast<__m128i*>(p + 16 * c), _mm256_castsi256_si128(chunk)); };
    whole(4, c4), whole(3, c3), whole(2, c2), whole(1, c1), whole(0, c0);
    low(0, c0), low(1, c1), low(2, c2), low(3, c3), low(4, c4);
}

// Values x[0, 16) in the lane order of store(), divided.
[[gnu::always_inline]] inline void divide16(const std::uint32_t* x, Divided& lo, Divided& hi, const Constants& k) {
    const auto at = [x](int i) { return _mm256_loadu_si256(reinterpret_cast<const __m256i*>(x + i)); };
    const auto both = [x](int i) { return _mm256_broadcastsi128_si256(_mm_loadu_si128(reinterpret_cast<const __m128i*>(x + i))); };
    const __m256i l = _mm256_blend_epi32(at(0), both(8), 0xF0), h = _mm256_blend_epi32(at(8), both(4), 0x0F);
    lo = divide(l, _mm256_srli_epi64(l, 32), k);
    hi = divide(h, _mm256_srli_epi64(h, 32), k);
}

// Text of x[0, count), count a positive multiple of 16, at p (16-byte aligned).
inline void format(char* p, const std::uint32_t* x, std::size_t count, const Constants& k) {
    Divided dl, dh;
    divide16(x, dl, dh, k);
    for (std::size_t i = 16; i < count; i += 16, p += 160) {
        Divided nl, nh;
        divide16(x + i, nl, nh, k);  // before the stores: 12% faster
        store(p, dl, dh, k);
        dl = nl, dh = nh;
    }
    store(p, dl, dh, k);
}

}  // namespace detail

inline constexpr std::size_t kBlock = 25600;  // values per write(2), a multiple of 16
inline constexpr std::size_t kTextBytes = 10 * kBlock;

// values[0, count), count >= 1, as fixed-width fields; text: kTextBytes bytes, 16-byte aligned.
// Blocks of 250 KB are longer than the Writer's buffer, so it hands each to write(2) directly.
inline void write(io::Writer& out, const std::uint32_t* values, std::size_t count, char* text) {
    const detail::Constants& k = detail::kConstants;
    for (std::size_t i = 0; i < count; i += kBlock) {
        const std::size_t n = std::min(kBlock, count - i), full = n / 16 * 16;
        if (full) detail::format(text, values + i, full, k);
        if (full < n) {
            alignas(32) std::uint32_t rest[16] = {};
            alignas(16) char last[160];
            std::memcpy(rest, values + i + full, (n - full) * sizeof(std::uint32_t));
            detail::format(last, rest, 16, k);
            std::memcpy(text + 10 * full, last, 10 * (n - full));
        }
        if (i + n == count) text[10 * n - 1] = '\n';
        out.write(std::string_view(text, 10 * n));
    }
}

}  // namespace fields

namespace {

using u32 = std::uint32_t;
using u64 = std::uint64_t;
using ntt::detail::add;
using ntt::detail::broadcast;
using ntt::detail::diff;
using ntt::detail::Factor;
using ntt::detail::kP;
using ntt::detail::multiply;
using ntt::detail::reduce;
using ntt::detail::slot;
using ntt::detail::Vec;

constexpr int kMaxLog = 20;
constexpr int kDirectLog = 7;                                // output levels m <= 7: direct
constexpr std::size_t kFold = std::size_t(1) << (kDirectLog - 2);  // their longest sequence
constexpr std::size_t kPadding = 16;                         // words after each array: kernels read past

u32 add_mod(u32 x, u32 y) {
    const u32 s = x + y;
    return std::min(s, s - kP);
}
u32 sub_mod(u32 x, u32 y) {
    const u32 d = x - y;
    return std::min(d, d + kP);
}
u32 mul_mod(u32 x, u32 y) { return u32(u64(x) * y % kP); }

constexpr u32 kHalf = (kP + 1) / 2;

// x < 4P -> x mod P.
Vec canonical(Vec x) { return reduce(reduce(x, 2 * kP), kP); }

// Bump allocation from one mapping in 2 MiB pages where the kernel allows. Never freed.
class Arena {
public:
    explicit Arena(std::size_t bytes) {
        constexpr std::size_t kHuge = std::size_t(1) << 21;
        bytes = (bytes + kHuge - 1) / kHuge * kHuge;
        void* p = ::mmap(nullptr, bytes + kHuge, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (p == MAP_FAILED) std::abort();
        const std::uintptr_t aligned = (reinterpret_cast<std::uintptr_t>(p) + kHuge - 1) & ~(kHuge - 1);
#ifdef MADV_HUGEPAGE
        ::madvise(reinterpret_cast<void*>(aligned), bytes, MADV_HUGEPAGE);
#endif
        next_ = reinterpret_cast<char*>(aligned);
        end_ = next_ + bytes;
    }

    // count words, 64-byte aligned, zero, then kPadding readable words.
    u32* words(std::size_t count) { return reinterpret_cast<u32*>(take(4 * (count + kPadding))); }
    char* bytes(std::size_t count) { return take(count); }

private:
    char* take(std::size_t count) {
        char* p = next_;
        next_ += (count + 63) & ~std::size_t(63);
        if (next_ > end_) std::abort();
        return p;
    }

    char *next_, *end_;
};

// Forward and inverse transforms of lib/ntt's tree with the leaves exposed. A transform of nv
// vectors (nv >= 8) splits x^(8 nv) - 1 into leaves x^8 - w; leaf v has the weight
// w = +-r[2k] (v = 4k, 4k + 1) or +-r[2k + 1] (v = 4k + 2, 4k + 3), the same at every length.
class Transform {
public:
    // Tables for transforms of up to max_nv vectors.
    Transform(Arena& arena, std::size_t max_nv) {
        const int lg = std::max(6, std::countr_zero(max_nv) + 3);
        roots_ = arena.words(ntt::detail::table_words(lg));
        inverse_roots_ = arena.words(ntt::detail::table_words(lg));
        ntt::detail::build_table(roots_, (std::size_t(1) << lg) / 16, ntt::detail::kRoots[0]);
        ntt::detail::build_table(inverse_roots_, (std::size_t(1) << lg) / 16, ntt::detail::kRoots[1]);
    }

    // Canonical f -> its leaves, canonical. top_done: f is canonical after the top layer
    // (radix 2 if nv is 2 4^j, else radix 4; see top_layer).
    void forward(Vec* f, std::size_t nv, bool top_done) const {
        if (std::countr_zero(nv) % 2) {
            const std::size_t h = nv / 2;
            if (!top_done) ntt::detail::forward_radix2(f, h, false);
            visit(f, h, 0);
            visit(f + h, h, 1);
        } else if (top_done) {
            const std::size_t h = nv / 4;
            for (std::size_t t = 0; t < 4; ++t) visit(f + t * h, h, t);
        } else {
            visit(f, nv, 0);
        }
    }

    // sqrt(-1) of the radix-4 top layer.
    Factor top_root() const { return Factor(roots_[1], roots_[9]); }

    // Canonical leaves of a transform of nv >= 4 vectors -> its input folded to 32 words,
    // canonical: the first four leaves are the transform of the fold.
    void fold(const Vec* leaves, u32* out) const {
        Vec f[4] = {leaves[0], leaves[1], leaves[2], leaves[3]};
        last_inverse(f, 0);  // 4 times the fold
        const Factor quarter(ntt::detail::power(4, kP - 2));
        for (int t = 0; t < 4; ++t) _mm256_storeu_si256(reinterpret_cast<Vec*>(out + 8 * t), reduce(multiply(f[t], quarter), kP));
    }

    // w of leaf v as a factor.
    Factor leaf_weight(std::size_t v) const {
        const u32* y = roots_ + slot(v / 4 * 2) + v / 2 % 2;
        return v % 2 ? Factor(kP - y[0], ~y[8]) : Factor(y[0], y[8]);  // q(P - w) = ~q(w)
    }

    // Leaves < 2P -> scale times the inverse transform, canonical. The inverse alone multiplies
    // by nv.
    void inverse(Vec* f, std::size_t nv, u32 scale) const {
        if (std::countr_zero(nv) % 2) {
            const std::size_t h = nv / 2;
            inverse_visit(f, h, 0);
            inverse_visit(f + h, h, 1);
            alignas(32) u32 s[16] = {};  // table layout: s at entry 1
            s[1] = scale;
            s[9] = ntt::detail::quotient(scale);
            ntt::kernels::scale_radix2(f, h, s);
        } else {
            const std::size_t h = nv / 4;
            for (std::size_t t = 0; t < 4; ++t) inverse_visit(f + t * h, h, t);
            ntt::detail::inverse_radix4(f, h, inverse_roots_, Factor(scale));
        }
    }

private:
    // Group k at stride h = nv / 4, then its children 4k + t.
    void visit(Vec* f, std::size_t nv, std::size_t k) const {
        if (nv == 4) return last_forward(f, k);
        const std::size_t h = nv / 4;
        if (k == 0)
            ntt::kernels::forward_identity(f, h, roots_);
        else
            ntt::kernels::forward(f, h, roots_ + slot(k), roots_ + slot(2 * k));
        for (std::size_t t = 0; t < 4; ++t) visit(f + t * h, h, 4 * k + t);
    }

    void inverse_visit(Vec* f, std::size_t nv, std::size_t k) const {
        if (nv == 4) return last_inverse(f, k);
        const std::size_t h = nv / 4;
        for (std::size_t t = 0; t < 4; ++t) inverse_visit(f + t * h, h, 4 * k + t);
        if (k == 0)
            ntt::kernels::inverse_identity(f, h, inverse_roots_);
        else
            ntt::kernels::inverse(f, h, inverse_roots_ + slot(k), inverse_roots_ + slot(2 * k));
    }

    // Group k with h = 1 (vectors 4k..4k + 3), inputs < 4P: the kernels need h even.
    void last_forward(Vec* f, std::size_t k) const {
        const u32 *x = roots_ + slot(k), *y = roots_ + slot(2 * k);
        const Factor fx(x[0], x[8]), fy(y[0], y[8]), fz(y[1], y[9]);
        const Vec f0 = reduce(f[0], 2 * kP), f1 = reduce(f[1], 2 * kP);
        const Vec xf2 = multiply(f[2], fx), xf3 = multiply(f[3], fx);  // < 2P
        const Vec a = reduce(add(f0, xf2), 2 * kP), c = reduce(diff(f0, xf2), 2 * kP);
        const Vec yb = multiply(add(f1, xf3), fy), zd = multiply(diff(f1, xf3), fz);
        f[0] = canonical(add(a, yb));
        f[1] = canonical(diff(a, yb));
        f[2] = canonical(add(c, zd));
        f[3] = canonical(diff(c, zd));
    }

    // Inverse of group k with h = 1, inputs and outputs < 2P.
    void last_inverse(Vec* f, std::size_t k) const {
        const u32 *x = inverse_roots_ + slot(k), *y = inverse_roots_ + slot(2 * k);
        const Factor fx(x[0], x[8]), fy(y[0], y[8]), fz(y[1], y[9]);
        const Vec ab = reduce(add(f[0], f[1]), 2 * kP), cd = reduce(add(f[2], f[3]), 2 * kP);
        const Vec amb = multiply(diff(f[0], f[1]), fy), cmd = multiply(diff(f[2], f[3]), fz);
        f[0] = reduce(add(ab, cd), 2 * kP);
        f[1] = reduce(add(amb, cmd), 2 * kP);
        f[2] = multiply(diff(ab, cd), fx);
        f[3] = multiply(diff(amb, cmd), fx);
    }

    u32 *roots_, *inverse_roots_;
};

// 64-bit lanes t < 2^63 -> t 2^-32 mod P in the high dword, below t / 2^32 + P.
Vec montgomery(Vec t) {
    const Vec m = _mm256_mul_epu32(t, broadcast(ntt::kernels::kNI));
    return _mm256_add_epi64(t, _mm256_mul_epu32(m, broadcast(kP)));
}

// 64-bit lanes t < 4P 2^32 -> t mod 2P 2^32 in [0, 2P 2^32), by the high dword alone.
Vec reduce_high(Vec t) {
    const Vec high_2p = _mm256_set1_epi64x(static_cast<long long>(2 * kP) << 32);
    return _mm256_min_epu32(t, _mm256_sub_epi32(t, high_2p));
}

// Sums of 64-bit products of x y mod (z^8 - w): coefficients 2i in even, 2i + 1 in odd. Both
// below 2P 2^32 on entry and exit: a product adds under 8 P^2 < 2P 2^32.
// window = [w x, x], y: canonical leaves.
void multiply_add(const u32* window, const u32* y, Vec& even, Vec& odd) {  // z^j x = window [8 - j, 16 - j)
#pragma GCC unroll 8
    for (int j = 0; j < 8; ++j) {
        const Vec yj = broadcast(y[j]);
        even = _mm256_add_epi64(even, _mm256_mul_epu32(_mm256_loadu_si256(reinterpret_cast<const Vec*>(window + 8 - j)), yj));
        odd = _mm256_add_epi64(odd, _mm256_mul_epu32(_mm256_loadu_si256(reinterpret_cast<const Vec*>(window + 9 - j)), yj));
    }
    even = reduce_high(even);
    odd = reduce_high(odd);
}

// Sums of multiply_add -> their value times 2^-32 mod P, < 2P.
Vec finish(Vec even, Vec odd) {
    const Vec r = _mm256_blend_epi32(_mm256_srli_epi64(montgomery(even), 32), montgomery(odd), 0xAA);  // < 3P
    return reduce(r, 2 * kP);
}

// One level of one factor: sign parts of length L = 2^(M-2), M = N - s.
struct Level {
    std::size_t length = 0;     // L, 0 for M < 2
    u32 sum = 0;                // sum of the level's values mod P
    u32 fold[2][kFold] = {};    // [+], [-] folded to min(L, kFold) words
    u32* part[2] = {};          // L > kFold: [+], [-], then their leaves; for b, then c's leaves
};

bool transformed(const Level& level) { return level.length > kFold; }

// Level s of x (2^n values) by sign and discrete log.
// For n >= kBlockedLog, x is held transposed: grid[c][h] = x[c + 2^B h], c < 2^B, h < kHeight,
// B = n - kRowLog, rows kPitch words apart. Level s (M = n - s >= kBlockedLog, b = M - kRowLog)
// has y[u] = x[2^s u] in row 2^s (u mod 2^b), column u >> b. With k = k_lo + 2^(b-2) k_hi,
// 5^k = 5^k_lo G^k_hi, G = 5^(2^(b-2)) = 1 mod 2^b: the row of +-5^k depends on k_lo alone, so
// eight consecutive k_lo use 16 rows (17 KiB) for all k_hi.
constexpr int kBlockedLog = 13;
constexpr int kRowLog = 8;
constexpr std::size_t kHeight = std::size_t(1) << kRowLog;
constexpr std::size_t kPitch = kHeight + 16;  // rows 2^s apart start in different L1 sets

Vec load(const u32* p) { return _mm256_loadu_si256(reinterpret_cast<const Vec*>(p)); }
void store(u32* p, Vec x) { _mm256_storeu_si256(reinterpret_cast<Vec*>(p), x); }

Vec add_canonical(Vec x, Vec y) {
    const Vec s = _mm256_add_epi32(x, y);
    return _mm256_min_epu32(s, _mm256_sub_epi32(s, broadcast(kP)));
}
Vec sub_canonical(Vec x, Vec y) {
    const Vec d = _mm256_sub_epi32(x, y);
    return _mm256_min_epu32(d, _mm256_add_epi32(d, broadcast(kP)));
}

void transpose(Vec (&r)[8]) {
    Vec t[8], u[8];
    for (int i = 0; i < 8; i += 2) {
        t[i] = _mm256_unpacklo_epi32(r[i], r[i + 1]);
        t[i + 1] = _mm256_unpackhi_epi32(r[i], r[i + 1]);
    }
    for (int i = 0; i < 8; i += 4) {
        u[i] = _mm256_unpacklo_epi64(t[i], t[i + 2]);
        u[i + 1] = _mm256_unpackhi_epi64(t[i], t[i + 2]);
        u[i + 2] = _mm256_unpacklo_epi64(t[i + 1], t[i + 3]);
        u[i + 3] = _mm256_unpackhi_epi64(t[i + 1], t[i + 3]);
    }
    for (int i = 0; i < 4; ++i) {
        r[i] = _mm256_permute2x128_si256(u[i], u[i + 4], 0x20);
        r[i + 4] = _mm256_permute2x128_si256(u[i], u[i + 4], 0x31);
    }
}

constexpr std::size_t kBand = 16;  // rows of x per pass: one cache line of each grid row

// Rows [first, first + kBand) of x (band, width = 2^B words each) -> their grid columns.
void to_grid(const u32* band, std::size_t width, std::size_t first, u32* grid) {
    for (std::size_t c = 0; c < width; c += 8)
        for (std::size_t h = 0; h < kBand; h += 8) {
            Vec r[8];
            for (std::size_t i = 0; i < 8; ++i) r[i] = load(band + (h + i) * width + c);
            transpose(r);
            for (std::size_t i = 0; i < 8; ++i) store(grid + (c + i) * kPitch + first + h, r[i]);
        }
}

// Inverse of to_grid.
void from_grid(const u32* grid, std::size_t width, std::size_t first, u32* band) {
    for (std::size_t c = 0; c < width; c += 8)
        for (std::size_t h = 0; h < kBand; h += 8) {
            Vec r[8];
            for (std::size_t i = 0; i < 8; ++i) r[i] = load(grid + (c + i) * kPitch + first + h);
            transpose(r);
            for (std::size_t i = 0; i < 8; ++i) store(band + (h + i) * width + c, r[i]);
        }
}

// Grid offsets of +-5^k (level s, M = m) for eight consecutive k_lo, stepping k_hi.
class UnitWalk {
public:
    UnitWalk(int m, int s, std::size_t k_lo) : b_(m - kRowLog), mask_(broadcast((u32(1) << m) - 1)) {
        const u32 mask = (u32(1) << m) - 1;
        u32 g = 5, p = 1;
        for (int i = 0; i < b_ - 2; ++i) g = g * g & mask;
        for (std::size_t i = 0; i < k_lo; ++i) p = p * 5 & mask;
        alignas(32) u32 lanes[8];
        for (u32& lane : lanes) lane = p, p = p * 5 & mask;
        unit_ = _mm256_load_si256(reinterpret_cast<const Vec*>(lanes));
        step_ = broadcast(g);
        const Vec low = _mm256_and_si256(unit_, broadcast((u32(1) << b_) - 1));  // odd: -u has 2^b - low
        row_pos_ = _mm256_mullo_epi32(_mm256_slli_epi32(low, s), broadcast(kPitch));
        row_neg_ = _mm256_mullo_epi32(_mm256_slli_epi32(_mm256_sub_epi32(broadcast(u32(1) << b_), low), s), broadcast(kPitch));
        row_neg_ = _mm256_add_epi32(row_neg_, broadcast(kHeight - 1));
    }

    // 5^k for the current k_hi; c times it, for c = 1 mod 2^b; the next k_hi.
    Vec unit() const { return unit_; }
    Vec times(u32 c) const { return _mm256_and_si256(_mm256_mullo_epi32(unit_, broadcast(c)), mask_); }
    void next() { unit_ = _mm256_and_si256(_mm256_mullo_epi32(unit_, step_), mask_); }

    // G^e mod 2^m, G = 5^(2^(b-2)) the step.
    u32 step_power(std::size_t e) const {
        const u32 mask = u32(_mm256_cvtsi256_si32(mask_)), g = u32(_mm256_cvtsi256_si32(step_));
        u32 r = 1;
        for (std::size_t i = 0; i < e; ++i) r = r * g & mask;
        return r;
    }

    // Offsets of u and -u, for u = 5^k times a power of the step.
    Vec positive(Vec u) const { return _mm256_add_epi32(row_pos_, _mm256_srli_epi32(u, b_)); }
    Vec negative(Vec u) const { return _mm256_sub_epi32(row_neg_, _mm256_srli_epi32(u, b_)); }

private:
    int b_;
    Vec mask_, unit_, step_, row_pos_, row_neg_;
};

// The top layer of Transform::forward on Ways canonical vectors at stride nv / Ways (Ways = 2:
// x^(8 nv) - 1 = (x^(4 nv) - 1)(x^(4 nv) + 1); Ways = 4: group 0 of the radix-4 tree), canonical.
template <int Ways>
void top_layer(Vec (&f)[Ways], const Factor& z) {
    if constexpr (Ways == 2) {
        const Vec x = f[0], y = f[1];
        f[0] = add_canonical(x, y);
        f[1] = sub_canonical(x, y);
    } else {
        const Vec s02 = add_canonical(f[0], f[2]), d02 = sub_canonical(f[0], f[2]);
        const Vec s13 = add_canonical(f[1], f[3]), zd13 = reduce(multiply(sub_canonical(f[1], f[3]), z), kP);
        f[0] = add_canonical(s02, s13);
        f[1] = sub_canonical(s02, s13);
        f[2] = add_canonical(d02, zd13);
        f[3] = sub_canonical(d02, zd13);
    }
}

// Level s (M = m) of the grid -> plus[k], minus[k] = y(5^k) +- y(-5^k), k < 2^(m-2), after
// top_layer<Ways>. k = k_lo + stride k_hi: the top layer's vectors are k_hi + i kHeight / Ways.
template <int Ways>
void gather_units(const u32* grid, int m, int s, const Factor& z, u32* plus, u32* minus) {
    const std::size_t stride = std::size_t(1) << (m - kRowLog - 2), rounds = kHeight / Ways;
    const auto* base = reinterpret_cast<const int*>(grid);
    for (std::size_t k = 0; k < stride; k += 8) {
        UnitWalk walk(m, s, k);
        u32 jump[Ways];
        for (int i = 0; i < Ways; ++i) jump[i] = walk.step_power(i * rounds);
        for (std::size_t j = k; j < k + rounds * stride; j += stride, walk.next()) {
            Vec p[Ways], q[Ways];
            for (int i = 0; i < Ways; ++i) {
                const Vec u = i ? walk.times(jump[i]) : walk.unit();
                const Vec xp = _mm256_i32gather_epi32(base, walk.positive(u), 4);
                const Vec xn = _mm256_i32gather_epi32(base, walk.negative(u), 4);
                p[i] = add_canonical(xp, xn);
                q[i] = sub_canonical(xp, xn);
            }
            top_layer(p, z);
            top_layer(q, z);
            for (int i = 0; i < Ways; ++i) {
                store(plus + j + i * rounds * stride, p[i]);
                store(minus + j + i * rounds * stride, q[i]);
            }
        }
    }
}

// Values plus[k] +- minus[k] at +-5^k, k < 2^(m-2) (canonical) -> level s (M = m) of the grid.
void scatter_units(const u32* plus, const u32* minus, int m, int s, u32* grid) {
    const std::size_t stride = std::size_t(1) << (m - kRowLog - 2);
    for (std::size_t k = 0; k < stride; k += 8) {
        UnitWalk walk(m, s, k);
        for (std::size_t j = k; j < k + kHeight * stride; j += stride, walk.next()) {
            alignas(32) u32 at_pos[8], at_neg[8], pos[8], neg[8];
            _mm256_store_si256(reinterpret_cast<Vec*>(at_pos), walk.positive(walk.unit()));
            _mm256_store_si256(reinterpret_cast<Vec*>(at_neg), walk.negative(walk.unit()));
            const Vec p = load(plus + j), q = load(minus + j);
            _mm256_store_si256(reinterpret_cast<Vec*>(pos), add_canonical(p, q));
            _mm256_store_si256(reinterpret_cast<Vec*>(neg), sub_canonical(p, q));
            for (std::size_t l = 0; l < 8; ++l) grid[at_pos[l]] = pos[l], grid[at_neg[l]] = neg[l];
        }
    }
}

// Work memory, in words.
struct Buffers {
    u32* band;      // n >= kBlockedLog: kBand rows of x, 2^(n-4); else x, 2^n
    u32* grid;      // n >= kBlockedLog: 2^(n-kRowLog) rows
    u32* small[2];  // levels with M < kBlockedLog: 2^min(n, kBlockedLog - 1) each
    char* text;     // 10 words of band, at least fields::kTextBytes

    Buffers(Arena& arena, int n) {
        const bool blocked = n >= kBlockedLog;
        band = arena.words(std::size_t(1) << (blocked ? n - 4 : n));
        grid = blocked ? arena.words((std::size_t(1) << (n - kRowLog)) * kPitch) : nullptr;
        for (u32*& p : small) p = arena.words(std::size_t(1) << std::min(n, kBlockedLog - 1));
        text = arena.bytes(std::max(fields::kTextBytes, blocked ? 10 * (std::size_t(1) << (n - 4)) : 0));
    }
};

// Levels with m >= kBlockedLog.
bool top_done(int m) { return m >= kBlockedLog; }

void gather(const u32* grid, int m, int s, const Factor& z, std::array<u32*, 2> out) {
    if ((m - 5) % 2)  // nv = 2^(m-5)
        gather_units<2>(grid, m, s, z, out[0], out[1]);
    else
        gather_units<4>(grid, m, s, z, out[0], out[1]);
}

// Sets up level (M = m >= 2); returns where its sign parts go.
std::array<u32*, 2> open_level(Level& level, int m, Arena& arena) {
    const std::size_t len = std::size_t(1) << (m - 2);
    level.length = len;
    if (!transformed(level)) return {level.fold[0], level.fold[1]};
    for (u32*& p : level.part) p = arena.words(len);
    return {level.part[0], level.part[1]};
}

// Sum of a level whose folds are written.
void close_level(Level& level) {
    u64 t = 0;
    for (std::size_t i = 0; i < std::min(level.length, kFold); ++i) t += level.fold[0][i];
    level.sum = u32(t % kP);
}

// Reads 2^n values and splits them into their levels.
// Parts of levels with m >= kBlockedLog are after the top layer; folds and sums of transformed
// levels are left to the caller.
void split(io::Reader& in, int n, Level* levels, Arena& arena, const Buffers& buffers, const Factor& z) {
    u32* cur = buffers.band;  // cur[i] = x[i 2^s], i < 2^m
    int s = 0;
    if (n >= kBlockedLog) {
        const int rows_log = n - kRowLog;
        const std::size_t width = std::size_t(1) << rows_log;
        for (std::size_t first = 0; first < kHeight; first += kBand) {
            in.read(buffers.band, kBand * width);
            to_grid(buffers.band, width, first, buffers.grid);
        }
        for (; n - s >= kBlockedLog; ++s) gather(buffers.grid, n - s, s, z, open_level(levels[s], n - s, arena));
        cur = buffers.small[0];
        for (std::size_t i = 0; i < std::size_t(1) << (n - s); ++i) {
            const std::size_t x = i << s;
            cur[i] = buffers.grid[(x & (width - 1)) * kPitch + (x >> rows_log)];
        }
    } else {
        in.read(cur, std::size_t(1) << n);
    }
    for (; s <= n; ++s) {
        const int m = n - s;
        Level& level = levels[s];
        if (m < 2) {
            level.sum = cur[m];
            continue;  // level s + 1 is cur[0]
        }
        u32* other = cur == buffers.small[0] ? buffers.small[1] : buffers.small[0];
        const auto out = open_level(level, m, arena);
        const u32 mask = (u32(1) << m) - 1;
        u32 u = 1;
        for (std::size_t k = 0; k < level.length; ++k, u = u * 5 & mask) {
            out[0][k] = add_mod(cur[u], cur[mask + 1 - u]);
            out[1][k] = sub_mod(cur[u], cur[mask + 1 - u]);
        }
        for (std::size_t i = 0; i < std::size_t(1) << (m - 1); ++i) other[i] = cur[2 * i];
        if (!transformed(level)) close_level(level);
        cur = other;
    }
}

// Writes c from its levels, top down: after the level of the units mod 2^m, c[i 2^(n-m)] for
// i < 2^m are known. Levels with m >= kBlockedLog go to the grid, which goes to the output
// kBand rows at a time.
class Assembly {
public:
    Assembly(int n, const Buffers& buffers, io::Writer& out, u32 zero)
        : n_(n), buffers_(buffers), out_(out), cur_(buffers.small[0]), other_(buffers.small[1]) {
        cur_[0] = zero;
        if (n == 0) fields::write(out_, cur_, 1, buffers_.text);
    }

    // m = 1: the unit 1.
    void push_odd(u32 value) {
        cur_[1] = value;
        if (n_ == 1) fields::write(out_, cur_, 2, buffers_.text);
    }

    // m >= 2: the values at +-5^k are plus[k] +- minus[k], k < 2^(m-2); canonical.
    void push(int m, const u32* plus, const u32* minus) {
        if (m >= kBlockedLog) {
            const int s = n_ - m, rows_log = n_ - kRowLog;
            const std::size_t width = std::size_t(1) << rows_log;
            if (m == kBlockedLog)  // c[x], x = i 2^(s+1): the smaller levels
                for (std::size_t i = 0; i < std::size_t(1) << (m - 1); ++i) {
                    const std::size_t x = i << (s + 1);
                    buffers_.grid[(x & (width - 1)) * kPitch + (x >> rows_log)] = cur_[i];
                }
            scatter_units(plus, minus, m, s, buffers_.grid);
            if (m == n_)
                for (std::size_t first = 0; first < kHeight; first += kBand) {
                    from_grid(buffers_.grid, width, first, buffers_.band);
                    write_band(kBand * width, first + kBand == kHeight);
                }
            return;
        }
        const std::size_t len = std::size_t(1) << (m - 2);
        for (std::size_t i = 0; i < 2 * len; ++i) other_[2 * i] = cur_[i];
        const u32 mask = (u32(1) << m) - 1;
        u32 u = 1;
        for (std::size_t k = 0; k < len; ++k, u = u * 5 & mask) {
            other_[u] = add_mod(plus[k], minus[k]);
            other_[mask + 1 - u] = sub_mod(plus[k], minus[k]);
        }
        if (m == n_) fields::write(out_, other_, std::size_t(1) << m, buffers_.text);
        std::swap(cur_, other_);
    }

private:
    // band[0, count) as fixed-width fields (as fields::write); count a multiple of 16.
    void write_band(std::size_t count, bool last) {
        fields::detail::format(buffers_.text, buffers_.band, count, fields::detail::kConstants);
        if (last) buffers_.text[10 * count - 1] = '\n';
        out_.write(std::string_view(buffers_.text, 10 * count));
    }

    int n_;
    const Buffers& buffers_;
    io::Writer& out_;
    u32 *cur_, *other_;
};

// Output level m <= kDirectLog: cyclic convolutions of the folds.
void direct_level(Assembly& c, int n, int m, const Level* a, const Level* b) {
    const std::size_t len = std::size_t(1) << (m - 2);
    u32 result[2][kFold];
    for (int e = 0; e < 2; ++e) {
        u64 acc[kFold] = {};
        for (int s = 0; s <= n - m; ++s) {
            const Level &x = a[s], &y = b[n - m - s];
            u32 fx[kFold] = {}, fy[kFold] = {};
            for (std::size_t k = 0; k < std::min(x.length, kFold); ++k) fx[k % len] = add_mod(fx[k % len], x.fold[e][k]);
            for (std::size_t k = 0; k < std::min(y.length, kFold); ++k) fy[k % len] = add_mod(fy[k % len], y.fold[e][k]);
            for (std::size_t i = 0; i < len; ++i)
                for (std::size_t k = 0; k < len; ++k) acc[(i + k) % len] = (acc[(i + k) % len] + u64(fx[i]) * fy[k]) % kP;
        }
        for (std::size_t k = 0; k < len; ++k) result[e][k] = u32(acc[k]);
    }
    for (auto& r : result)
        for (std::size_t k = 0; k < len; ++k) r[k] = mul_mod(r[k], kHalf);
    c.push(m, result[0], result[1]);
}

// [w x, x] for leaf v of the levels s <= k of a (sign e).
using Windows = std::array<std::array<u32, 16>, kMaxLog + 1>;

void make_windows(const Level* a, int e, int k, std::size_t v, const Factor& w, Windows& windows) {
    for (int s = 0; s <= k; ++s) {
        const Vec x = load(a[s].part[e] + 8 * v);
        store(windows[s].data(), reduce(multiply(x, w), kP));
        store(windows[s].data() + 8, x);
    }
}

// Leaves [first, end) of the levels s <= k, sign e: level t of c gets the sum over s + t' = t of
// a_s b_t', in place of b_t. The windows of leaf v + 1 are stored before the products of leaf v
// load those of v: unaligned loads from recent stores stall.
void band_products(const Level* a, Level* b, int e, int k, std::size_t first, std::size_t end, const Transform& transform) {
    Windows windows[2];
    make_windows(a, e, k, first, transform.leaf_weight(first), windows[0]);
    for (std::size_t v = first; v < end; ++v) {
        if (v + 1 < end) make_windows(a, e, k, v + 1, transform.leaf_weight(v + 1), windows[(v + 1 - first) % 2]);
        const Windows& x = windows[(v - first) % 2];
        for (int t = k; t >= 0; --t) {  // b_t is last read for level t
            Vec even = _mm256_setzero_si256(), odd = even;
            for (int s = 0; s <= t; ++s) multiply_add(x[s].data(), b[t - s].part[e] + 8 * v, even, odd);
            store(b[t].part[e] + 8 * v, finish(even, odd));
        }
    }
}

// Output level m > kDirectLog from its leaves in b[n - m].
void transform_level(Assembly& c, int n, int m, const Level* b, const Transform& transform) {
    const std::size_t len = std::size_t(1) << (m - 2), nv = len / 8;
    const u32 scale = mul_mod(mul_mod(ntt::detail::power(u32(nv), kP - 2), ntt::detail::kR), kHalf);
    u32* const* out = b[n - m].part;
    for (int e = 0; e < 2; ++e) transform.inverse(reinterpret_cast<Vec*>(out[e]), nv, scale);
    c.push(m, out[0], out[1]);
}

void solve() {
    io::Reader in;
    const int n = in.read<int>();
    const std::size_t size = std::size_t(1) << n;
    // Under 8 words per value, the text (under 10 bytes per value) and 64 KiB of padding.
    Arena arena(4 * 8 * size + 10 * size + fields::kTextBytes + (64 << 10));
    const Buffers buffers(arena, n);

    const Transform transform(arena, std::max<std::size_t>(size / 32, 8));
    const int levels = std::max(n - kDirectLog, 0);  // transformed: s < levels
    std::array<Level, kMaxLog + 1> a, b;
    for (auto* x : {&a, &b}) {
        split(in, n, x->data(), arena, buffers, transform.top_root());
        for (int s = 0; s < levels; ++s) {
            Level& level = (*x)[s];
            for (int e = 0; e < 2; ++e) {
                auto* f = reinterpret_cast<Vec*>(level.part[e]);
                transform.forward(f, level.length / 8, top_done(n - s));
                transform.fold(f, level.fold[e]);
            }
            close_level(level);
        }
    }

    io::Writer out;
    u32 zero = 0;
    for (int s = 0; s <= n; ++s)
        for (int t = n - s; t <= n; ++t) zero = add_mod(zero, mul_mod(a[s].sum, b[t].sum));
    Assembly c(n, buffers, out, zero);
    if (n >= 1) {
        u32 odd = 0;
        for (int s = 0; s <= n - 1; ++s) odd = add_mod(odd, mul_mod(a[s].sum, b[n - 1 - s].sum));
        c.push_odd(odd);
    }
    for (int m = 2; m <= std::min(n, kDirectLog); ++m) direct_level(c, n, m, a.data(), b.data());

    if (n > kDirectLog) {
        for (int e = 0; e < 2; ++e)  // leaves [nv of level k + 1, nv of level k) are in levels 0..k
            for (int k = levels - 1; k >= 0; --k)
                band_products(a.data(), b.data(), e, k, k + 1 < levels ? a[k + 1].length / 8 : 0, a[k].length / 8, transform);
        for (int m = kDirectLog + 1; m <= n; ++m) transform_level(c, n, m, b.data(), transform);
    }
}

#ifdef __ELF__
// The program runs from the executable's pre-initializers, before the C++ runtime initializes
// iostreams and locales (unused here). _exit skips their teardown too.
void run_early(int, char**, char**) {
    solve();
    ::_exit(0);
}

[[gnu::used, gnu::section(".preinit_array")]] void (*const preinit)(int, char**, char**) = run_early;
#endif

}  // namespace

int main() { solve(); }  // reached only without .preinit_array support
